

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2368c81c-7e01-427b-b9af-b6771bf8f355', '2026-05-22 07:22:00.858', NULL, 'Lý Chiêu Hoàng chính thức trút bỏ áo ngự, nhường ngôi cho chồng là Trần Cảnh (Trần Thái Tông). Triều đại nhà Trần chính thức được thành lập, mở ra kỷ nguyên phát triển rực rỡ của nước Đại Việt.', '1226-01-10', 'Nhà Trần chính thức thành lập');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('87ba49a8-1bb6-4eb4-88b2-674490d4ddb3', '2026-05-22 07:22:00.858', NULL, 'Vua Trần Thái Tông phong sắc cho Thái sư Trần Thủ Độ làm Quốc thượng phụ, nắm giữ binh quyền và điều hành các chính sự quan trọng hàng đầu của vương triều mới.', '1226-01-14', 'Thần cơ diệu toán Trần Thủ Độ làm Quốc thượng phụ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('48601f52-b614-4e48-832e-fc2b5949c866', '2026-05-22 07:22:00.858', NULL, 'Thái thượng hoàng Trần Thừa (tức Trần Thái Tổ), người đặt nền móng vĩ đại cho cơ nghiệp của hoàng triều Trần, băng hà tại Phụ Thiên cung, Thăng Long.', '1234-02-17', 'Thái thượng hoàng Trần Thừa băng hà');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6f31ba8c-752f-4df0-89b6-51ed65a7b00e', '2026-05-22 07:22:00.858', NULL, 'Quân dân nhà Trần dưới sự chỉ huy của vua Trần Thái Tông và Thái tử Trần Hoảng mở cuộc phản công chiến lược tại Đông Bộ Đầu, đánh tan quân xâm lược Mông Cổ, giải phóng kinh thành Thăng Long.', '1258-01-29', 'Đại thắng Đông Bộ Đầu lần thứ nhất');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6825d441-92d8-417f-86da-c60b278ad49a', '2026-05-22 07:22:00.858', NULL, 'Vua Trần Thái Tông chính thức nhường ngôi cho Thái tử Trần Hoảng (Trần Thánh Tông) và lui về làm Thái thượng hoàng. Đây là sự khởi đầu của chế độ lưỡng đầu (vua và thượng hoàng) đặc trưng thời Trần giúp ổn định triều chính.', '1258-03-30', 'Trần Thái Tông nhường ngôi cho Trần Thánh Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('723de16b-0b15-4adb-8d4a-52e5b9e215d7', '2026-05-22 07:22:00.858', NULL, 'Thái thượng hoàng Trần Thái Tông, vị hoàng đế khai quốc anh minh của nhà Trần, người trực tiếp lãnh đạo kháng chiến chống Mông Cổ lần thứ nhất, băng hà tại điện Vạn Thọ, kinh thành Thăng Long.', '1277-05-04', 'Thượng hoàng Trần Thái Tông qua đời');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('5073cc8e-ec0c-4550-86c3-cc6f1d82ba0d', '2026-05-22 07:22:00.858', NULL, 'Vua Trần Thánh Tông nhường ngôi cho Thái tử Trần Khâm (tức hoàng đế Trần Nhân Tông), một vị minh quân lỗi lạc và là người sáng lập ra Thiền phái Trúc Lâm Yên Tử sau này.', '1278-11-08', 'Trần Thánh Tông nhường ngôi cho Trần Nhân Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('66634bed-b546-44be-8032-5fb57663626e', '2026-05-22 07:22:00.858', NULL, 'Vua Trần Nhân Tông triệu tập Hội nghị Bình Than gồm các vương hầu, tướng lĩnh nhằm bàn kế sách công thủ và phân chia hướng quân chống lại đại quân xâm lược nhà Nguyên lần thứ hai.', '1282-11-09', 'Khai mạc Hội nghị Bình Than lịch sử');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b68ac6d3-89fd-4d76-be94-5fe01f42458f', '2026-05-22 07:22:00.858', NULL, 'Danh tướng Trần Bình Trọng bị quân Nguyên bắt giữ trong trận đồn Đà Mạc. Ông khẳng khái từ chối sự dụ dỗ phong vương của giặc bằng câu nói bất hủ: ''Ta thà làm quỷ nước Nam, chứ không thèm làm vương đất Bắc'', sau đó bị giặc sát hại.', '1285-02-26', 'Bảo nghĩa vương Trần Bình Trọng hy sinh anh dũng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('9dd8fe4e-8ddf-468f-a926-c4c47b7aff5a', '2026-05-22 07:22:00.858', NULL, 'Quân dân Đại Việt dưới sự tổng chỉ huy của Quốc công Tiết chế Trần Hưng Đạo đại thắng thủy quân nhà Nguyên trên sông Bạch Đằng, bắt sống các tướng Ô Mã Nhi, Phàn Tiếp, đập tan hoàn toàn dã tâm xâm lược nước ta của nhà Nguyên.', '1288-04-09', 'Đại thắng sông Bạch Đằng năm 1288');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d9e90232-ddd7-4a54-be9f-ac32a936477f', '2026-05-22 07:22:00.858', NULL, 'Quốc công Tiết chế Hưng Đạo Đại Vương Trần Quốc Tuấn - vị anh hùng dân tộc vĩ đại, nhà quân sự thiên tài kiệt xuất thời Trần qua đời tại vương phủ Vạn Kiếp (Chí Linh, Hải Dương).', '1300-09-05', 'Hưng Đạo Đại Vương Trần Quốc Tuấn qua đời');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f03e382a-62a6-46bf-9e07-43cd6f797626', '2026-05-22 07:22:00.858', NULL, 'Công chúa Huyền Trân lên đường sang Chiêm Thành kết duyên cùng quốc vương Chế Mân. Cuộc hôn nhân đổi lại hai châu Ô, Lý (vùng đất từ Quảng Trị đến Thừa Thiên Huế ngày nay) cho Đại Việt.', '1306-05-22', 'Huyền Trân Công chúa lên đường hạ giá Chế Mân');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ad99f55f-d425-46ae-b99f-c831fa2fd2cb', '2026-05-22 07:22:00.858', NULL, 'Thái thượng hoàng Trần Nhân Tông (Trúc Lâm Đầu Đà) - vị vua anh hùng kiệt xuất đồng thời là Sơ tổ Chi phái Thiền Trúc Lâm Việt Nam nhập Niết bàn tại am Ngọa Vân trên núi Yên Tử.', '1308-12-16', 'Phật hoàng Trần Nhân Tông nhập Niết bàn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('bb6b2f34-1058-4f58-a879-10a2635de193', '2026-05-22 07:22:00.858', NULL, 'Dưới áp lực thao túng quyền lực khốc liệt của quyền thần Hồ Quý Ly, vua Trần Thuận Tông bị cưỡng ép nhường ngôi cho con trai mới 3 tuổi là Trần An (Trần Thiếu Đế).', '1398-03-15', 'Trần Thuận Tông bị ép nhường ngôi cho Thiếu Đế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('433d0a30-c893-450b-9a76-7b16e6b0e0fa', '2026-05-22 07:22:00.858', NULL, 'Hồ Quý Ly chính thức phế truất vua Trần Thiếu Đế, tự lập làm vua và đổi quốc hiệu thành Đại Ngu. Triều đại nhà Trần chính thức sụp đổ sau 175 năm trị vì huy hoàng với nhiều chiến công hiển hách.', '1400-03-15', 'Nhà Trần sụp đổ, nhà Hồ thành lập');



INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('083749fb-5c95-4cc7-ac5b-be152db71378', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Thái Tông tiến hành nghi lễ tế Giao tại đàn tế ngoại ô kinh thành Thăng Long, chính thức khẳng định thiên mệnh của triều Trần trước toàn thể quốc dân.', '1226-02-15', 'Trần Thái Tông làm lễ tế Trời Đất');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b6d9ad8b-ec7f-4026-a8b4-78ee1499a9dd', '2026-05-22 07:27:57.328', NULL, 'Cựu hoàng hậu triều Lý (mẹ của Lý Chiêu Hoàng) chính thức rời hoàng cung Thăng Long để xuất gia tu hành, khép lại một chương lịch sử của triều đại cũ.', '1227-04-12', 'Hoàng thái hậu triều Lý xuất gia');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('c4e8f534-6341-4a90-8488-1d956b1ad6ec', '2026-05-22 07:27:57.328', NULL, 'Thái sư Trần Thủ Độ chỉ đạo biên soạn và ban hành bộ Quốc triều thông chế nhằm luật hóa các quy định hành chính, quan chế và luật pháp của vương triều Trần.', '1230-03-22', 'Ban hành bộ Quốc triều thông chế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('346cc000-c470-4834-b6b8-f6d4e73a08ff', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần cải tổ hệ thống hành chính địa phương, đổi tên các đơn vị hương, giáp từ thời Lý thành đơn vị xã, đặt chức Xã quan để quản lý dân cư.', '1231-05-18', 'Đổi các hương, giáp thành xã');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8b37cba6-fef3-4357-a86b-33340d9d2340', '2026-05-22 07:27:57.328', NULL, 'Triều đình nhà Trần tổ chức khoa thi Thái học sinh (tương đương Tiến sĩ) đầu tiên nhằm tuyển chọn nhân tài rộng rãi trong nhân dân, không phân biệt xuất thân.', '1232-08-25', 'Mở khoa thi Thái học sinh đầu tiên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4083a079-81cf-4ba4-97d3-4231210bfe48', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Thái Tông cho lập Thẩm hình viện, một cơ quan tư pháp chuyên trách việc xét xử và rà soát lại các vụ án oan sai trong cả nước.', '1236-11-05', 'Thành lập Thẩm hình viện');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d27edc42-044a-4679-8b42-a1112bcd517b', '2026-05-22 07:27:57.328', NULL, 'Do mâu thuẫn gia đình và triều chính, Phụng Càn vương Trần Liễu (anh trai vua) đem quân khởi loạn trên sông Cái nhưng sau đó được Trần Thủ Độ và vua giảng hòa.', '1237-05-14', 'Sự biến sông Cái của Trần Liễu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('be79fb5c-7b36-4144-94ad-03737f2acebc', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần thực hiện cải cách hành chính quy mô lớn, chia toàn bộ lãnh thổ quốc gia thành 12 lộ, đặt các chức An phủ sứ để cai trị tinh gọn hơn.', '1242-02-10', 'Chia nước Đại Việt thành 12 lộ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('10ee3299-7005-4545-8703-d61e5b0dae10', '2026-05-22 07:27:57.328', NULL, 'Triều đình ban hành chỉ dụ quy định các khoa thi Hương tại địa phương sẽ được tổ chức định kỳ 7 năm một lần để tạo nguồn cử tử cho thi hội.', '1244-09-11', 'Quy định luật thi hương định kỳ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('bd275383-9ab0-471f-988f-84751ea4d6f3', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần chính thức định ra danh hiệu Tam khôi (Trạng nguyên, Bảng nhãn, Thám hoa) cho ba người đỗ cao nhất trong khoa thi Đình.', '1246-06-20', 'Định lệ thi Tam khôi thời Trần');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('242a4df6-c010-4751-ac48-bd3530608a14', '2026-05-22 07:27:57.328', NULL, 'Khoa thi Định năm Đinh Mùi ghi danh Thần đồng Nguyễn Hiền đỗ Trạng nguyên khi mới 12 tuổi, trở thành vị Trạng nguyên trẻ tuổi nhất trong lịch sử Việt Nam.', '1247-08-15', 'Nguyễn Hiền đỗ Trạng nguyên năm 12 tuổi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f9e3085b-d9c8-4951-8a4e-fb9cf8bfc263', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần ra lệnh cho các lộ đắp đê từ đầu nguồn đến bờ biển để ngăn lũ lụt, gọi là đê Quai Vạc, đồng thời đặt chức Hà đê sứ để trông nom.', '1248-03-05', 'Khởi công đắp đê Quai Vạc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6e4689cb-2b44-405a-9af6-071944e2583c', '2026-05-22 07:27:57.328', NULL, 'Do Chiêm Thành thường xuyên quấy nhiễu biên giới phía Nam, vua Trần Thái Tông trực tiếp cầm quân đi trừng phạt để giữ vững bình yên vùng biên ải.', '1252-01-30', 'Trần Thái Tông thân chinh phạt Chiêm Thành');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('db7c729b-b246-4ff8-ba3b-4c15f19cae11', '2026-05-22 07:27:57.328', NULL, 'Triều đình cho xây dựng Giảng võ đường tại Thăng Long làm nơi huấn luyện quân sự cao cấp, tập hợp binh pháp và rèn luyện võ nghệ cho các tướng lĩnh.', '1253-08-24', 'Thành lập Giảng võ đường');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('fb3602a9-7a87-4c14-a0d7-84ab2df8e2eb', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần cho lập Quốc học viện và đúc tượng Chu Công, Khổng Tử để làm nơi giảng dạy kinh sách kinh điển, thúc đẩy Nho học phát triển mạnh mẽ.', '1253-10-15', 'Sáng lập Quốc học viện Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4316a90c-a7a8-4b81-99e7-653f98500423', '2026-05-22 07:27:57.328', NULL, 'Triều đình chia ngạch Trạng nguyên thành hai loại: Kinh trạng nguyên (cho người vùng đồng bằng) và Trại trạng nguyên (cho người vùng thanh nghệ biên viễn).', '1256-04-11', 'Quy định lệ thi chọn Kinh trạng nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8cbd1946-bc67-4365-a079-8ecf82ca2931', '2026-05-22 07:27:57.328', NULL, 'Quân xâm lược Mông Cổ áp sát biên giới, vua Trần Thái Tông trực tiếp ngự giá chỉ huy trận Bình Lệ Nguyên. Nghe lời khuyên của Lê Tần, vua chủ động rút lui bảo toàn lực lượng.', '1257-12-12', 'Trận chiến Bình Lệ Nguyên anh dũng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7468b187-ac21-4f95-955b-8f3497fb487d', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần cho xây dựng hành cung Thiên Trường (Nam Định) - quê hương bản quán của dòng họ Trần, biến nơi đây thành kinh đô thứ hai sau Thăng Long.', '1262-03-14', 'Xây dựng hành cung Thiên Trường');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1aa9484a-f331-41aa-abec-b4ddc1bcd174', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần ban chiếu ban quyền cho các công chúa, vương hầu chiêu mộ dân nghèo phiêu tán đi khai hoang vùng ven biển, lập nên các điền trang quy mô lớn.', '1266-02-28', 'Cho phép vương hầu khai hoang lập điền trang');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1fdf9348-2ae5-404e-876c-b670877fe243', '2026-05-22 07:27:57.328', NULL, 'Hàn lâm viện Học sĩ Lê Văn Hưu dâng lên vua Trần Thánh Tông bộ ''Đại Việt Sử ký'' gồm 30 quyển. Đây là bộ chính sử đầu tiên mang tính bước ngoặt của nền sử học nước nhà.', '1272-03-20', 'Lê Văn Hưu hoàn thành Đại Việt Sử Ký');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('aa0478a8-3eb1-4cfe-b0d0-5e01e383eff9', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Thánh Tông xuống chiếu cho phép hàng vạn người Hoa từ phương Bắc chạy trốn ách thống trị của quân Nguyên được định cư tại vùng ven biển Đại Việt.', '1274-10-05', 'Tiếp nhận người Tống tị nạn Nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d6ef48b9-97d4-4477-9ba4-2b29ff96b30a', '2026-05-22 07:27:57.328', NULL, 'Hưng Đạo Vương Trần Quốc Tuấn tổ chức đại diễn trận và duyệt binh tại vùng chiến lược Vạn Kiếp, chuẩn bị tinh thần kháng chiến cho toàn quân.', '1275-06-18', 'Trần Quốc Tuấn duyệt binh tại Vạn Kiếp');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('fa782609-113c-4abb-9879-9b520a66d44e', '2026-05-22 07:27:57.328', NULL, 'Sứ giả nhà Nguyên là Sài Thung dẫn đầu đoàn bộ hạ nghênh ngang tiến vào Thăng Long nhằm uy hiếp, bắt ép vua Trần sang chầu Hốt Tất Liệt.', '1281-05-12', 'Sứ giả nhà Nguyên Sài Thung tới Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('3cc9ad65-8857-44be-86a4-e21aea8223cd', '2026-05-22 07:27:57.328', NULL, 'Trước nguy cơ xâm lược cận kề từ nhà Nguyên, vua Trần Nhân Tông phong Trần Quốc Tuấn làm Quốc công Tiết chế, thống lĩnh toàn bộ quân đội Đại Việt.', '1283-07-22', 'Trần Quốc Tuấn làm Quốc công Tiết chế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4d95213f-37fb-430d-8a55-692dd8189897', '2026-05-22 07:27:57.328', NULL, 'Để cổ vũ tinh thần yêu nước và ý chí quyết chiến của binh sĩ trước cuộc chiến sinh tử, Trần Quốc Tuấn viết bài ''Hịch tướng sĩ'' lay động lòng người.', '1284-09-30', 'Trần Quốc Tuấn soạn Hịch tướng sĩ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('55c68cb1-4eda-4a48-9b59-2af61568cbd2', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Nhân Tông triệu tập các bậc phụ lão trong cả nước về điện Diên Hồng để hỏi kế đánh giặc. Điện Diên Hồng vang dội tiếng hô đồng thanh: ''ĐÁNH!''.', '1285-01-10', 'Hội nghị Diên Hồng lịch sử khai mạc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e70f5fda-8743-4c19-99c1-81bc7ea04ac7', '2026-05-22 07:27:57.328', NULL, 'Chiêu Văn vương Trần Nhật Duật chỉ huy liên quân Đại Việt đánh tan quân Nguyên do Toa Đô chỉ huy tại cửa Hàm Tử, bẻ gãy một cánh quân chủ lực của địch.', '1285-05-25', 'Đại thắng Hàm Tử quan vang dội');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('fb2033d0-9171-4cb8-947d-0d59e905548d', '2026-05-22 07:27:57.328', NULL, 'Thượng tướng Trần Quang Khải tổng chỉ huy trận công kích thần tốc vào bến Chương Dương, đánh bại thủy quân Nguyên, mở đường giải phóng hoàn toàn kinh thành Thăng Long.', '1285-06-10', 'Đại thắng Chương Dương độ giải phóng Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('5da5e321-8777-4555-a385-2c75064a93df', '2026-05-22 07:27:57.328', NULL, 'Bị quân Trần truy kích dữ dội ở biên giới phía Bắc, trấn nam vương Thoát Hoan của nhà Nguyên phải chui vào ống đồng để quân lính khiêng chạy trốn thoát thân.', '1285-06-28', 'Thoát Hoan chui ống đồng trốn về nước');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1838bc3a-8e6f-4532-9a14-362f2aa34eee', '2026-05-22 07:27:57.328', NULL, 'Nuốt hận bại trận, Hốt Tất Liệt điều động Thoát Hoan dẫn 30 vạn đại quân cùng hàng trăm chiến thuyền ồ ạt tràn qua biên giới Đại Việt lần thứ ba.', '1287-11-20', 'Thoát Hoan dẫn quân Nguyên xâm lược lần 3');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('47a126e6-74a4-49ee-9b83-3b4e3e69b713', '2026-05-22 07:27:57.328', NULL, 'Phó tướng Trần Khánh Dư mai phục và đánh tan đoàn thuyền lương khổng lồ của Trương Văn Hổ tại Vân Đồn, cắt đứt hoàn toàn nguồn lương nhu yếu tử huyệt của quân Nguyên.', '1288-01-15', 'Trần Khánh Dư đại thắng Vân Đồn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('66efbcd1-2e37-4099-bc00-8c442c57ff7f', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Nhân Tông xét duyệt và ban thưởng tước vị cao quý cho các công thần có công lao vĩ đại trong hai cuộc kháng chiến chống Nguyên Mông thần thánh.', '1289-05-02', 'Đại định công thần kháng chiến chống Nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('21fd5afa-72c7-4532-9de6-682f88219bb5', '2026-05-22 07:27:57.328', NULL, 'Nhà Trần thực hiện sách lược ngoại giao mềm dẻo sau chiến tranh, đón tiếp sứ bộ nhà Nguyên sang nối lại bang giao hòa bình trên thế ngẩng cao đầu.', '1292-04-18', 'Tiếp đón phái đoàn ngoại giao Nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('599847df-6fbb-4986-8dc2-7de6933c701f', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Nhân Tông nhường ngôi cho Thái tử Trần Thuyên (Trần Anh Tông), lui về ngự ở hành cung Vũ Lâm Ninh Bình rồi lên núi Yên Tử tu hành.', '1293-03-09', 'Trần Nhân Tông nhường ngôi cho Trần Anh Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('44919740-54bf-450d-a574-01b717f210ba', '2026-05-22 07:27:57.328', NULL, 'Phật hoàng Trần Nhân Tông chính thức thống nhất các dòng thiền cũ để khai sáng ra Thiền phái Trúc Lâm Yên Tử - dòng thiền thuần Việt mang đậm tinh thần nhập thế.', '1299-10-24', 'Trần Nhân Tông sáng lập Thiền phái Trúc Lâm');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2732be30-cafc-4c2c-ba1b-0314fabd6ed4', '2026-05-22 07:27:57.328', NULL, 'Trong chuyến du hành hóa độ tại phương Nam, Phật hoàng đến Chiêm Thành và hứa gả công chúa Huyền Trân cho Quốc vương Chế Mân để kết tình hòa hảo.', '1301-06-05', 'Phật hoàng Trần Nhân Tông du ngoạn Chiêm Thành');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('0affc4a3-8647-4f84-913c-8c87285678ca', '2026-05-22 07:27:57.328', NULL, 'Triều đình tổ chức khoa thi lớn, chọn được danh sĩ Mạc Đĩnh Chi đỗ Trạng nguyên. Ông là người có tướng mạo xấu xí nhưng tài năng xuất chúng, danh chấn hai nước.', '1304-03-12', 'Khoa thi Thái học sinh tuyển chọn Mạc Đĩnh Chi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('981802c3-7127-4607-b0f8-c77c7455999f', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Anh Tông nhường ngôi cho Thái tử Trần Mạnh (Trần Minh Tông). Tân vương là người có lòng nhân hậu, trọng dụng các bậc hiền thần như Chu Văn An.', '1314-04-03', 'Trần Anh Tông nhường ngôi cho Trần Minh Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f942beaf-ac4d-4a4a-9413-80989880ac79', '2026-05-22 07:27:57.328', NULL, 'Thái thượng hoàng Trần Anh Tông - vị vua có công giữ vững kỷ cương triều chính và bảo vệ biên cương vững chắc - qua đời tại cung Trùng Quang.', '1320-05-17', 'Thượng hoàng Trần Anh Tông băng hà');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a6533a7d-f576-4541-b842-b396b4867ebb', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Minh Tông ra lệnh khảo hạch nghiêm ngặt đức tài của toàn bộ quan lại từ trung ương đến địa phương nhằm loại bỏ những kẻ tham nhũng, lười biếng.', '1323-09-08', 'Khảo hạch quan lại toàn quốc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ab9106a4-6b42-4b9d-a1ae-e28a943633f8', '2026-05-22 07:27:57.328', NULL, 'Vua Trần Minh Tông nhường ngôi cho con trai mới 10 tuổi là Trần Vượng (Trần Hiến Tông) nhằm giữ vững truyền thống lưỡng đầu chế bảo hộ hoàng tộc.', '1329-02-15', 'Trần Minh Tông nhường ngôi cho Trần Hiến Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('87fa7d91-bdc6-46da-a354-c33a91aedb11', '2026-05-22 07:27:57.328', NULL, 'Thượng hoàng Trần Minh Tông dù tuổi cao vẫn quyết định ngự giá thân chinh tiến quân vào vùng biên giới phía Tây đánh dẹp quân Ai Lao quấy nhiễu dân lành.', '1335-11-22', 'Trần Minh Tông thân chinh dẹp loạn Ai Lao');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('70941ea8-4719-45e6-b167-ca441a3b837e', '2026-05-22 07:27:57.328', NULL, 'Sau khi vua Hiến Tông yểu mệnh qua đời, Trần Hạo (Trần Dụ Tông) được lập lên ngôi, mở đầu thời kỳ trị vì đầy biến động khép lại hưng thịnh của nhà Trần.', '1341-06-21', 'Trần Dụ Tông chính thức lên ngôi hoàng đế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f2835ace-c6fa-4292-a518-76b572b95f3f', '2026-05-22 07:27:57.328', NULL, 'Tư nghiệp Quốc Tử Giám Chu Văn An bất bình trước cảnh gian thần hoành hành, dũng cảm dâng lên vua Dụ Tông tờ ''Thất trảm sớ'' đòi chém đầu 7 kẻ nịnh thần.', '1356-08-14', 'Thầy giáo Chu Văn An dâng Thất trảm sớ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('5db07cf9-4efe-4bfa-9353-43c3f7228757', '2026-05-22 07:27:57.328', NULL, 'Các vương hầu nhà Trần đứng đầu là Trần Phủ dấy binh lật đổ kẻ ngoại tộc Dương Nhật Lễ, giành lại ngai vàng cho dòng họ Trần. Trần Phủ lên ngôi (Trần Nghệ Tông).', '1370-11-15', 'Cuộc đảo chính lật đổ Dương Nhật Lễ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('34129df0-d388-41fc-b4d1-2fada3d5e60e', '2026-05-22 07:27:57.328', NULL, 'Vua Nghệ Tông nhường ngôi cho em trai là Trần Kính (Trần Duệ Tông) để lên làm Thượng hoàng, cố gắng vực dậy đất nước trước họa xâm lăng từ Chiêm Thành.', '1373-02-27', 'Trần Nghệ Tông nhường ngôi cho Trần Duệ Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('86ad3205-1d52-43eb-bae2-a80fb6076254', '2026-05-22 07:27:57.328', NULL, 'Do chủ quan khinh địch khi thân chinh đánh Chiêm Thành, vua Trần Duệ Tông lọt vào trận địa mai phục của Chế Bồng Nga tại thành Đồ Bàn và tử trận cùng toàn quân.', '1377-03-23', 'Vua Trần Duệ Tông tử trận tại thành Đồ Bàn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('213214ee-16c7-49ca-87fa-f184649e7b37', '2026-05-22 07:27:57.328', NULL, 'Nhận lệnh thống lĩnh quân đội, Hồ Quý Ly tổ chức trận địa phục kích lớn tiêu diệt sinh lực quân Chiêm Thành tại cửa sông Thần Đầu, chặn đứng đà tiến của giặc.', '1380-05-19', 'Hồ Quý Ly phá quân Chiêm tại sông Thần Đầu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b44c0bdc-6617-433a-877a-bec75aa0c24b', '2026-05-22 07:27:57.328', NULL, 'Tại trận thủy chiến trên sông Hải Triều, danh tướng Trần Khát Chân sử dụng hỏa súng thần cơ bắn thẳng vào chiến thuyền hoàng gia, tiêu diệt bạo chúa Chiêm Thành Chế Bồng Nga.', '1390-01-23', 'Trần Khát Chân bắn chết Chế Bồng Nga');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e968fdcf-f2a6-4057-854d-b3115a1c5d7a', '2026-05-22 07:27:57.328', NULL, 'Quyền thần Hồ Quý Ly ép buộc vua Trần Thuận Tông phải bỏ kinh thành Thăng Long để dời đô vào thành Tây Đô (Thanh Hóa), dọn đường cho việc cướp ngôi.', '1397-04-14', 'Hồ Quý Ly ép triều đình dời đô về Thanh Hóa');



INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e2d13641-b2fc-4b35-a176-680b7159b10e', '2026-05-22 07:29:22.857', NULL, 'Thái sư Trần Thủ Độ điều động binh lực vây quét thế lực cát cứ lực lượng phản loạn Nguyễn Nộn ở vùng Bắc Giang, từng bước thống nhất giang sơn về một mối.', '1228-06-18', 'Trần Thủ Độ dẹp loạn Nguyễn Nộn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('0ffe7e99-cda9-43e3-a604-6799928ba07a', '2026-05-22 07:29:22.857', NULL, 'Nhà Trần ban bố sắc lệnh ép buộc tất cả những người mang họ Lý trong nước phải đổi sang họ Nguyễn nhằm xóa nhòa hoàn toàn tầm ảnh hưởng và ký ức về vương triều cũ.', '1232-05-20', 'Đổi họ Lý trong thiên hạ thành họ Nguyễn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('493e2c2e-0698-4614-8055-46f28bd26c24', '2026-05-22 07:29:22.857', NULL, 'Triều đình nhà Trần triển khai đợt đo đạc và khảo hạch diện tích ruộng đất, phân định rõ ruộng công, ruộng tư để làm căn cứ đánh thuế công bằng.', '1233-04-15', 'Khảo hạch tô thuế đất đai toàn quốc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('14ef463f-f6b1-4fcb-87e5-1f0b07877284', '2026-05-22 07:29:22.857', NULL, 'Vua Trần Thái Tông quy định lại màu sắc, kiểu dáng triều phục và mũ áo cho các bậc quan văn, quan võ từ nhất phẩm đến cửu phẩm để nghiêm trang triều nghi.', '1235-09-01', 'Hoàn thành sửa đổi triều phục quan lại');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('abf7efda-8f93-49ff-996d-2880214f30b0', '2026-05-22 07:29:22.857', NULL, 'Nhà Trần ban hành quy chế thuế thân (thuế đinh) dựa trên số lượng ruộng sở hữu, người không có ruộng hoặc ít ruộng được miễn giảm sâu, bớt gánh nặng cho dân nghèo.', '1239-02-11', 'Định ngạch thuế đinh chi tiết');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1eb014b5-cfe2-43ee-aeb4-55d622963266', '2026-05-22 07:29:22.857', NULL, 'Vua Trần Anh Tông lặn lội về vương phủ Vạn Kiếp thăm hỏi sức khỏe Quốc công tiết chế Trần Quốc Tuấn khi ông đang lâm bệnh nặng và hỏi kế sách giữ nước lâu bền.', '1300-06-24', 'Trần Anh Tông thăm viếng Hưng Đạo Vương');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2fa0c01b-85d5-4e1b-99f2-dd0bfe910e43', '2026-05-22 07:29:22.857', NULL, 'Hoàng đế Trần Thái Tông dẫn đầu ngự lâm quân tuần du dọc vùng biên cương Quảng Nguyên nhằm củng cố các đồn lũy phòng thủ tiền tiêu và vỗ về đồng bào thiểu số.', '1241-10-08', 'Trần Thái Tông tuần du biên giới phía Bắc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a7601b4e-cfee-451b-b9fc-efad98f29e85', '2026-05-22 07:29:22.857', NULL, 'Triều đình chính thức đặt ra chức quan Đồn điền sứ chuyên trách việc chiêu mộ dân phiêu tán, khai khẩn đất hoang lập đồn điền bổ sung quân lương khẩn cấp.', '1243-12-05', 'Lập chức đồn điền sứ chuyên trách nông nghiệp');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('74a30e57-2967-49ee-9c8b-817a32c6b001', '2026-05-22 07:29:22.857', NULL, 'Kinh thành Thăng Long và các lộ lân cận hứng chịu một trận đại hồng thủy, triều đình lập tức trích ngân khố cứu trợ và huy động hàng vạn dân phu gia cố đê sông Hồng.', '1245-07-14', 'Trận bão lớn tàn phá đê điều Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('02cf8714-b185-4a7e-9425-1725a1cee03e', '2026-05-22 07:29:22.857', NULL, 'Vượt qua các rào cản nghi lễ hoàng tộc khắt khe, Trần Quốc Tuấn chính thức kết duyên cùng công chúa Thiên Thành, tạo nên một giai thoại tình yêu nổi tiếng thời Trần.', '1251-04-22', 'Trần Quốc Tuấn kết duyên cùng Công chúa Thiên Thành');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('24390e58-4810-4a40-b3db-7c6a18ede7d4', '2026-05-22 07:29:22.857', NULL, 'Nhà Trần tiếp thu tiến bộ thiên văn, biên soạn và ban hành lịch Thụ Thời giúp nông dân nắm bắt chuẩn xác thời vụ canh tác lúa nước.', '1254-11-18', 'Ban hành lịch Thụ Thời áp dụng canh tác');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2ea4aa5a-3b6a-4eef-9092-049a5556d5f0', '2026-05-22 07:29:22.857', NULL, 'Khai mạc đợt đại sát hạch võ nghệ tại Giảng Võ Đường nhằm chọn ra những chiến binh tinh nhuệ nhất bổ sung vào cấm quân bảo vệ hoàng thành.', '1255-08-09', 'Sát hạch võ nghệ tuyển chọn thân binh');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d1b11194-78e1-4554-a34d-06a79591b076', '2026-05-22 07:29:22.857', NULL, 'Ba sứ giả của tướng Ngột Lương Hợp Thai đem thư dụ hàng của Mông Cổ đến Thăng Long. Vua Trần Thái Tông lập tức hạ lệnh tống giam vào ngục tối.', '1257-03-12', 'Sứ giả Mông Cổ đầu tiên đặt chân đến Đại Việt');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b7139ce7-79a4-4128-90d6-aebf6427d982', '2026-05-22 07:29:22.857', NULL, 'Nhà Trần thực hiện chính sách ''nhu viễn'', ban tước và gả công chúa cho các vị tù trưởng có uy tín lớn vùng biên giới Tây Bắc để thắt chặt lòng trung thành.', '1261-02-05', 'Tặng tước vương cho các tù trưởng miền núi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('94c626cf-e007-4b99-991d-3237f870e4c8', '2026-05-22 07:29:22.857', NULL, 'Vua Trần Thánh Tông cho mở thêm các lớp học Nho học xung quanh kinh thành Thăng Long, cấp kinh phí kinh sách nhằm nâng cao dân trí cho con em bá tánh.', '1265-10-19', 'Trần Thánh Tông lập nhà học ở kinh đô');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('dcf4b71a-94b0-4c42-86c0-4293ac341891', '2026-05-22 07:29:22.857', NULL, 'Ban hành quy định ngặt nghèo trong việc tuyển dụng quan chức phục vụ trong nội đình (Nội thị gia), ngăn chặn nguy cơ hoạn quan can chính phá hoại triều đình.', '1267-07-25', 'Định bảng ngạch tuyển chọn nội thị hành chính');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('0188c70c-9510-426c-b1bb-7a1da8caa0b8', '2026-05-22 07:29:22.857', NULL, 'Mùa đông năm Mậu Thìn, nhà vua trực tiếp xuống chiếu răn dạy các quan địa phương không được bắt phu phen vào mùa cấy cày để bảo vệ sức sản xuất.', '1268-12-01', 'Vua Trần Thánh Tông xuống chiếu khuyến nông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('43467660-3bd8-4586-928d-1696585a7353', '2026-05-22 07:29:22.857', NULL, 'Hoàng tộc nhà Trần tổ chức đại lễ khánh thành và đúc chuông lớn tại chùa Phổ Minh (Nam Định), đưa ngôi chùa này thành trung tâm phật giáo lớn của đất nước.', '1269-04-11', 'Tổ chức đại lễ khánh thành chùa Phổ Minh');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('9ce779b8-c8ca-416a-898e-79e59afab6a3', '2026-05-22 07:29:22.857', NULL, 'Sau khi nhà Tống hoàn toàn thất thủ trước quân Nguyên tại trận Nhai Môn, nhà Trần thiết lập các biện pháp phòng thủ nghiêm ngặt đề phòng giặc tràn xuống phía Nam.', '1279-03-19', 'Nhà Trần phái sứ bộ sang viếng nhà Tống sụp đổ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('70024189-1860-4a66-b2ec-6750a13946a2', '2026-05-22 07:29:22.857', NULL, 'Hốt Tất Liệt lập hành tỉnh ở Chiêm Thành, cử Toa Đô mang quân áp sát mạn Nam Đại Việt, hình thành thế gọng kìm nguy hiểm bao vây nước ta.', '1282-04-14', 'Nhà Nguyên lập Tỉnh Chiêm Thành uy hiếp Đại Việt');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('0ea6bd4d-b298-480a-ac51-d31cdc6f65b4', '2026-05-22 07:29:22.857', NULL, 'Quốc công tiết chế hoàn thành việc biên soạn cuốn ''Binh thư yếu lược'', dâng lên vua Trần Nhân Tông làm cẩm nang quân sự tối cao cho cuộc chiến sắp tới.', '1284-12-25', 'Trần Quốc Tuấn dâng binh pháp cho vua');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f6e08038-f17b-4a15-9d75-abfe6377fa47', '2026-05-22 07:29:22.857', NULL, 'Hưng Đạo Vương trực tiếp chỉ huy cấm quân chặn đánh quyết liệt thủy quân Nguyên do Ô Mã Nhi dẫn đầu tại cửa biển A Lỗ, làm chậm tốc độ hành quân của giặc.', '1285-03-15', 'Trận ác chiến tại đồn A Lỗ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ccbf5cd5-6ad7-4230-be19-9c912a25c5f6', '2026-05-22 07:29:22.857', NULL, 'Danh tướng Trần Nhật Duật và Trần Quốc Toản chỉ huy phục kích đánh tan quân Nguyên tại bến Tây Kết, chém chết tướng giặc khét tiếng Toa Đô tại trận.', '1285-05-18', 'Đại thắng trận Tây Kết lần thứ nhất');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6c82cbf5-2a6c-43b7-9f49-61746a9b0f2c', '2026-05-22 07:29:22.857', NULL, 'Quân dân nhà Trần tổ chức mai phục lớn trên tuyến sông Như Nguyệt, tiêu diệt hàng ngàn quân Nguyên đang rã ngũ tháo chạy hỗn loạn về nước.', '1285-06-20', 'Trận phục kích truy kích địch tại sông Như Nguyệt');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4eabeb00-27e0-4905-9f13-caa945584fa0', '2026-05-22 07:29:22.857', NULL, 'Nhận định hướng rút quân bằng đường thủy của giặc, Trần Quốc Tuấn chỉ huy quân dân đẽo gỗ lim, cắm hàng vạn cọc nhọn bọc sắt xuống lòng sông Bạch Đằng.', '1288-02-22', 'Trần Quốc Tuấn cho cắm cọc gỗ trên sông Bạch Đằng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('69023f54-6a3a-4fd1-829d-6ba89f41bebf', '2026-05-22 07:29:22.857', NULL, 'Thủy quân Trần tiếp tục đánh tan các cụm thuyền chiến bảo vệ còn sót lại của nhà Nguyên tại Ninh Bình, cắt đứt hoàn toàn hy vọng tiếp viện.', '1288-03-29', 'Trận cửa biển Thần Đầu bẻ gãy hậu cần giặc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f90c141d-8102-470b-9510-d5908a802283', '2026-05-22 07:29:22.857', NULL, 'Triều đình làm lễ khánh thành công trình Thái Miếu long trọng tại phủ Long Hưng (Thái Bình), nơi thờ tự linh vị các vị tiên đế khai quốc hoàng triều Trần.', '1290-08-11', 'Khánh thành Thái Miếu triều Trần tại Long Hưng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7e77f46e-9838-4216-92e9-9ed2333a0b0c', '2026-05-22 07:29:22.857', NULL, 'Vua Anh Tông phái các tướng lĩnh trấn thủ vùng biên viễn phía Tây tiến hành tiễu trừ các toán giặc cướp tràn qua từ biên giới Ai Lao.', '1294-11-05', 'Trần Anh Tông phái quân thảo phạt tiễu phỉ biên giới');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2dc68e9a-ec49-4098-b6aa-9fa49271a9ce', '2026-05-22 07:29:22.857', NULL, 'Để giữ vững kỷ luật quân đội, vua Trần Anh Tông ban sắc lệnh nghiêm cấm đánh bạc, chặt ngón tay hoặc xử tử những binh sĩ, tướng lĩnh vi phạm.', '1296-03-14', 'Định tội nghiêm khắc hành vi đánh bạc trong cấm quân');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('40006826-6993-4970-a168-e769385e60ab', '2026-05-22 07:29:22.857', NULL, 'Các nghệ nhân Đại Việt hoàn thiện kỹ thuật dệt gấm lụa cao cấp, đưa sản phẩm lụa Thăng Long trở thành mặt hàng giao thương quý giá với các nước lân cận.', '1302-09-17', 'Tiếp thụ kỹ thuật dệt lụa tiên tiến');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a7297aef-73ee-4970-a38d-2e629e2754b0', '2026-05-22 07:29:22.857', NULL, 'Phái đoàn ngoại giao cao cấp của Chiêm Thành mang vàng bạc, hương liệu quý đến kinh đô Thăng Long thúc tiến hôn sự giữa Chế Mân và Huyền Trân công chúa.', '1305-05-12', 'Sứ bộ Chiêm Thành dâng lễ vật cầu hôn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2c0f5085-1bfb-4283-9a92-9a39f749ec07', '2026-05-22 07:29:22.857', NULL, 'Vua Anh Tông trực tiếp cầm quân tiến xuống biên giới phía Nam nhằm giải quyết tranh chấp lãnh thổ và ổn định tình hình trật tự xã hội.', '1311-12-01', 'Trần Anh Tông親征 (thân chinh) dẹp loạn biên cương phía Nam');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a8106309-0648-4147-a5c5-4323cea9a23a', '2026-05-22 07:29:22.857', NULL, 'Ban hành bộ luật bắt buộc quan lộ phải túc trực bám sát các đoạn đê xung yếu trong suốt các tháng hè, lơ là sẽ bị cách chức, tịch thu gia sản.', '1315-06-20', 'Sửa đổi điều lệ đê điều mùa bão lũ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1d70cbf7-13a5-4cad-a696-7d1e1128fbfa', '2026-05-22 07:29:22.857', NULL, 'Nhận lệnh thống lĩnh cấm quân phản công, Đỗ Khắc Chung lập mưu đánh tan lực lượng xâm lấn của quân Chiêm Thành tại vùng biên ải phía Nam.', '1318-02-14', 'Danh tướng Đỗ Khắc Chung đại phá quân Chiêm');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4f989e87-02fa-46ef-843d-388d2b80a39c', '2026-05-22 07:29:22.857', NULL, 'Vua Trần Minh Tông cho dựng các bia đá trang trọng tại hoàng thành để tuyên dương đức độ và công lao của các vị đại thần có đóng góp lớn cho quốc gia.', '1322-07-11', 'Trần Minh Tông lập bia ghi công trạng công thần');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b148e8b3-ea49-493f-b09e-444a8ac0ac00', '2026-05-22 07:29:22.857', NULL, 'Một toán quân biên phòng nhà Nguyên tràn qua cướp bóc tại vùng Thạch Lâm (Cao Bằng), nhà Trần lập tức gửi thư trách tước ngoại giao mạnh mẽ ép rút quân.', '1326-10-05', 'Nhà Nguyên xâm phạm biên giới Cao Bằng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e773d8b9-057a-4d5b-b0ba-4f4ab1966d67', '2026-05-22 07:29:22.857', NULL, 'Khoa thi năm Canh Ngọ ghi danh danh sĩ Phạm Sư Mạnh đỗ cao. Ông trở thành một nhà thơ, nhà kinh tế và đại thần có tầm ảnh hưởng lớn cuối thời Trần.', '1330-04-18', 'Nhà thơ Phạm Sư Mạnh đỗ Thái học sinh');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8aaaa63c-905e-4ef5-9095-e5976e5c1f3f', '2026-05-22 07:29:22.857', NULL, 'Thượng hoàng Trần Minh Tông chỉ đạo các nhà địa lý hoàn thành việc vẽ lại bản đồ ranh giới hành chính của các lộ miền núi phía Bắc để dễ bề quản lý trị an.', '1337-11-12', 'Định lại bản đồ hành chính các lộ phía Bắc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6978ebd8-0fc3-4097-99bb-40227e867f4b', '2026-05-22 07:29:22.857', NULL, 'Triều đình hoàn thành việc bổ sung, hiệu đính và ban hành bộ ''Quốc triều hình luật'' (Luật hình triều Trần) nhằm tăng cường tính minh bạch pháp lý.', '1343-05-27', 'Biên soạn bộ sách Quốc triều hình luật mới');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f0575be3-e7ef-4898-b2b6-d8473703e008', '2026-05-22 07:29:22.857', NULL, 'Nền nông nghiệp Đại Việt điêu đứng vì đại hạn, vua Trần Dụ Tông ăn chay nằm đất làm lễ cầu mưa tại chùa Diên Hựu và mở kho lương cứu đói bá tánh.', '1348-08-22', 'Hạn hán nghiêm trọng kéo dài, vua làm lễ cầu mưa');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2bc37a7a-6b8e-4016-a72f-e253ccaca019', '2026-05-22 07:29:22.857', NULL, 'Do mâu thuẫn giai cấp và tô thuế nặng nề thời Dụ Tông, thủ lĩnh Ngô Bệ tụ tập hàng vạn nông dân nghèo dấy binh khởi nghĩa tại vùng Hải Dương.', '1352-03-09', 'Khởi nghĩa nông dân Ngô Bệ bùng nổ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('06ade760-b3cb-4f5a-ad20-ec17c84b973e', '2026-05-22 07:29:22.857', NULL, 'Vua Trần Dụ Tông cho phép tổ chức các hội diễn hát chèo, múa rối nước quy mô lớn tại cung đình, thúc đẩy nghệ thuật sân khấu dân gian phát triển mạnh.', '1362-02-14', 'Mở hội thi hát xướng nghệ thuật dân gian');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('73999550-93b6-4ef2-9f61-6927cb6169a4', '2026-05-22 07:29:22.857', NULL, 'Sau khi vua Dụ Tông băng hà không có con nối dõi, Dương Nhật Lễ (vốn là con người hát chèo) được lập lên ngôi, mở đầu chuỗi ngày u tối của cung đình.', '1369-06-15', 'Dương Nhật Lễ soán ngôi nhà Trần');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e1b0f106-a806-49c4-99d4-b4bcffff5f6b', '2026-05-22 07:29:22.857', NULL, 'Lợi dụng tình hình Đại Việt rối ren sau đảo chính, bạo chúa Chiêm Thành Chế Bồng Nga dẫn hạm đội vượt biển đánh thẳng vào Thăng Long, cướp bóc và thiêu rụi cung điện.', '1371-03-24', 'Chế Bồng Nga đem quân thiêu rụi kinh thành Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('c956e697-1121-4528-997d-ffab4af21274', '2026-05-22 07:29:22.857', NULL, 'Thượng hoàng Trần Nghệ Tông xuống chiếu tổng động viên, bắt buộc tất cả nam đinh khỏe mạnh phải tòng quân để kháng cự thế lực Chiêm Thành nguy hiểm.', '1375-08-11', 'Ban hành lệnh tuyển binh quy mô lớn toàn quốc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1a52ae7f-826d-4030-ab3b-3dae783340c6', '2026-05-22 07:29:22.857', NULL, 'Sau khi từ quan, danh sư Chu Văn An cùng các học trò xây dựng am học tại Chí Linh (Hải Dương), tiếp tục sự nghiệp dạy học, giữ gìn khí tiết Nho gia.', '1383-12-01', 'Thầy trò Chu Văn An lập am tu học tại núi Phượng Hoàng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a62da4e8-79f0-43f0-b5f4-8c0217fb42a4', '2026-05-22 07:29:22.857', NULL, 'Nắm trọn quyền sinh sát trong tay, Hồ Quý Ly ép Thượng hoàng Nghệ Tông phế truất và thắt cổ chết vua Trần Phế Đế tại chùa Tư Phúc, lập Thuận Tông lên thay.', '1388-12-05', 'Hồ Quý Ly bức hại vua Trần Phế Đế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('862b1912-b6c6-46b0-aa9c-8110eaa510e2', '2026-05-22 07:29:22.857', NULL, 'Hồ Quý Ly viết sách Minh Đạo nhằm phê phán một số quan điểm Nho giáo giáo điều, dọn đường tư tưởng cho cuộc cải cách toàn diện kinh tế, xã hội sau này.', '1392-05-19', 'Hồ Quý Ly soạn sách ''Minh Đạo'' cải cách tư tưởng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b3d543a6-cfdd-4614-8cfc-80213d18db6f', '2026-05-22 07:29:22.857', NULL, 'Thượng hoàng Trần Nghệ Tông, chỗ dựa chính trị cuối cùng của hoàng tộc nhà Trần qua đời, khiến quyền lực triều đình hoàn toàn rơi vào tay ngoại thích Hồ Quý Ly.', '1394-12-15', 'Thượng hoàng Trần Nghệ Tông băng hà');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7178e319-1925-4ee8-882c-821cb81b20f1', '2026-05-22 07:29:22.857', NULL, 'Hồ Quý Ly ép vua Trần ban hành tiền giấy ''Thông bảo hội sao'', hạ lệnh thu hồi toàn bộ tiền đồng trong nhân dân. Đây là tờ tiền giấy đầu tiên trong lịch sử Việt Nam.', '1396-04-20', 'Ban hành tiền giấy Thông bảo hội sao đầu tiên');



INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('60a9daa8-04e1-4c95-bc41-164c6b6a2458', '2026-05-22 07:52:35.683', NULL, 'Trần Thái Tông tổ chức lễ đại phong tước vương, hầu cho các tôn thất và công thần có công phò tá lập nên vương triều nhà Trần.', '1226-08-11', 'Phân phong tước vị cho các công thần khai quốc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('52e60890-2461-47bd-9880-faaafc5d4652', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần ban hành quy định chi tiết về tang phục và thời gian để tang cho các bậc đế vương, vương hầu và bá quan văn võ.', '1229-10-05', 'Định quy chế tang phục hoàng gia');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ddfc34ef-b736-4ca2-a589-b78fd184aeda', '2026-05-22 07:52:35.683', NULL, 'Triều đình chuẩn y và ban hành biểu thuế thương quan thống nhất trên toàn quốc, thúc đẩy việc giao thương tại các cửa khẩu và bến sông.', '1230-09-15', 'Ban hành quy định về biểu thuế buôn bán');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d3763db6-9fc6-47b4-ab22-ebc8d42ea0a1', '2026-05-22 07:52:35.683', NULL, 'Triều đình tiến hành đợt tổng kiểm tra dân số, lập sổ hộ tịch chi tiết đến từng xã để quản lý nhân đinh và bổ sung binh lính.', '1238-03-22', 'Lập sổ hộ tịch (sổ đinh) quy mô lớn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('831afcd3-c2ba-4d80-88a3-99c235207242', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần điều phu dịch và thợ thủ công lên vùng Lạng Sơn mở mỏ khai thác đồng, cung cấp nguyên liệu đúc tiền và rèn vũ khí.', '1240-11-10', 'Khai mở mỏ đồng tại Lạng Sơn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('c305b063-d7f6-4006-b086-85e215cbc91a', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Thái Tông hạ chiếu cho lập các kho Nghĩa Thương ở từng lộ, tích trữ lúa gạo phòng khi thiên tai, mất mùa để cứu đói cho dân.', '1249-02-08', 'Lập kho Nghĩa Thương cứu tế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7e555b40-b321-4aa2-b4a6-61f2d085f4d3', '2026-05-22 07:52:35.683', NULL, 'Thái sư Trần Thủ Độ tổ chức lại hệ thống cấm binh bảo vệ kinh thành, chọn lựa những thanh niên khỏe mạnh từ vùng hạ lưu sông Hồng sung vào quân ngũ.', '1250-12-25', 'Trần Thủ Độ củng cố hệ thống cấm quân');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1e720c55-56c8-42aa-9c2f-1aecce014679', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần cho đúc và lưu hành đồng tiền kim loại ''Nguyên Phong Thông Bảo'', giúp chuẩn hóa hệ thống tiền tệ và thúc đẩy kinh tế hàng hóa.', '1256-09-18', 'Đúc tiền đồng Nguyên Phong Thông Bảo');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8ec9015e-1ed2-4f97-b635-2a90bc287f6c', '2026-05-22 07:52:35.683', NULL, 'Thượng hoàng Thái Tông và vua Thánh Tông mở đợt phong thưởng và cất nhắc hàng loạt sĩ quan có công trong cuộc kháng chiến chống Mông Cổ lần thứ nhất.', '1258-05-12', 'Tuyển trạch tướng tài sau chiến tranh');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('0d2e6852-96cc-4c2f-8cd0-6f12d1582b96', '2026-05-22 07:52:35.683', NULL, 'Triều đình lập cơ quan Thái y viện, đặt chức Y quan chuyên trách việc chữa bệnh cho hoàng tộc và phổ biến bài thuốc dân gian trong nhân dân.', '1260-07-20', 'Lập chức Y quan chăm sóc sức khỏe');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1ed98dc0-1677-424a-bc26-a455158c1da4', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Thánh Tông ban chỉ dụ cấp thêm đất và miễn giảm thuế cho thương nhân nước ngoài đến buôn bán tại cảng Vân Đồn, biến nơi đây thành trung tâm thương mại sầm uất.', '1263-04-14', 'Mở rộng bến cảng Vân Đồn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('76845dcb-6b5a-4256-a17f-8b765a9d1924', '2026-05-22 07:52:35.683', NULL, 'Thái sư Trần Thủ Độ, nhân vật kiệt xuất có công sáng lập và kiến thiết vương triều Trần, từ trần ở tuổi 71. Triều đình truy tặng ông tước Thượng phụ Thái sư.', '1264-08-30', 'Trần Thủ Độ qua đời');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4064dff9-a85e-47f8-8543-1e65186db068', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần áp dụng chế độ ''ngụ binh ư nông'' một cách triệt để hơn, cho binh sĩ luân phiên về quê làm ruộng vào thời bình để tự túc lương thực.', '1270-01-22', 'Cải cách binh chế đồn trú');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('c604d0a2-c588-4dae-a7d5-deb93813b13c', '2026-05-22 07:52:35.683', NULL, 'Triều đình quy hoạch lại lực lượng quân sự, chính thức thành lập đội Tượng binh (quân voi) quy mô lớn, huấn luyện bài bản để tăng cường sức mạnh đột phá.', '1273-11-09', 'Thiết lập đội tượng binh chính quy');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('174eeef5-465f-4e5c-a3c9-1cd2bc613346', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần đặt ra chức Khuyến nông sứ tại các địa phương, chuyên trách việc đôn đốc dân chúng gieo hạt, gặt hái và phát triển thủy lợi.', '1276-06-15', 'Thành lập cơ quan Khuyến nông sứ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('94a570a6-318c-4dec-a39f-350bf6a45add', '2026-05-22 07:52:35.683', NULL, 'Trịnh Giác Mật mưu phản ở vùng Đà Giang. Trần Nhật Duật không mang theo vũ khí, đi một mình vào doanh trại địch thu phục Giác Mật bằng sự chân thành và tài ngoại giao.', '1280-02-28', 'Trịnh Giác Mật nổi dậy ở Đà Giang');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('da947721-7e6c-4411-b146-b8fe2104aeab', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Nhân Tông cử Trần Di Ái làm chánh sứ sang Đại Đô dâng sản vật và nỗ lực ngoại giao nhằm trì hoãn âm mưu xâm lược của nhà Nguyên.', '1284-01-18', 'Cử sứ bộ sang nhà Nguyên đàm phán');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('29156205-ea43-433f-8600-e8dc37ca3501', '2026-05-22 07:52:35.683', NULL, 'Quân Trần dưới sự chỉ huy của Trần Quốc Tuấn phải rút lui chiến lược khỏi phòng tuyến Vạn Kiếp trước sức ép quá lớn của đại quân Thoát Hoan, bảo toàn chủ lực.', '1285-04-10', 'Trận Vạn Kiếp khốc liệt');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f0945402-b8a5-4cb4-a1e5-b888566c2ff5', '2026-05-22 07:52:35.683', NULL, 'Chuẩn bị cho cuộc chiến lần 3, vua Trần Nhân Tông xuống chiếu lệnh cho các lộ ven biển, ven sông khẩn trương hạ thủy hàng trăm chiến thuyền mới.', '1286-09-05', 'Huy động dân đinh đóng chiến thuyền');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('dd8a8cea-e17b-4432-8f67-dbe9cb0b2957', '2026-05-22 07:52:35.683', NULL, 'Đại quân Nguyên Mông do Thoát Hoan chỉ huy ồ ạt vượt qua ải Nội Bàng, tiến vào lãnh thổ Đại Việt, mở màn cuộc xâm lược lần thứ ba.', '1287-12-10', 'Quân Nguyên vượt ải Nội Bàng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('09ffc1a6-4661-4491-aae7-c9cd600893f8', '2026-05-22 07:52:35.683', NULL, 'Sau thảm bại Bạch Đằng, Thoát Hoan cùng tàn quân phải bỏ ngựa, cắt rừng tháo chạy trối chết qua đường Tư Minh (Lạng Sơn) về nước.', '1288-04-15', 'Thoát Hoan tháo chạy qua ngõ Tư Minh');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('3a6ea630-9cdb-4f27-9f3d-6f1acc790cb4', '2026-05-22 07:52:35.683', NULL, 'Để hàn gắn vết thương chiến tranh, vua Trần Nhân Tông ban lệnh đại ân xá cho những kẻ vì sợ hãi mà lỡ đầu hàng giặc, đốt bỏ tráp giấy tờ phản quốc.', '1289-09-22', 'Vua Trần Nhân Tông ân xá thiên hạ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('dbd54fd1-a5a7-473a-8380-b93890a4b051', '2026-05-22 07:52:35.683', NULL, 'Nhà Nguyên cử Trương Lập Đạo sang Thăng Long mang theo sắc thư của Hốt Tất Liệt uy hiếp, bắt vua Trần sang chầu. Vua Trần kiên quyết từ chối.', '1291-03-08', 'Sứ Nguyên đòi vua Trần sang chầu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('766ce062-3648-41b8-9bc2-471d479ea37a', '2026-05-22 07:52:35.683', NULL, 'Thượng hoàng Trần Nhân Tông chỉ đạo việc khắc ván và in ấn bộ kinh Đại Tạng, phân phát cho các chùa chiền lớn trong cả nước.', '1295-05-17', 'In ấn và phổ biến kinh Phật Đại Tạng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7064590a-e87e-4169-94f8-47626efcf4e4', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Anh Tông đi tuần tra vùng ven biển Hải Đông (Quảng Ninh ngày nay) để củng cố hệ thống phòng thủ hàng hải và động viên ngư dân bám biển.', '1297-08-14', 'Trần Anh Tông tuần thú vùng Hải Đông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('615e38e1-b667-42ec-94e6-c69f0b3288ed', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần ban hành quy chế sát hạch lại viên (viên chức cấp dưới) chặt chẽ, yêu cầu phải giỏi tính toán, viết chữ đẹp và am hiểu pháp luật.', '1298-10-25', 'Quy định tiêu chuẩn thi lại viên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('06254ad8-87b4-46f4-b89a-36dc7c29b19e', '2026-05-22 07:52:35.683', NULL, 'Phật hoàng Trần Nhân Tông tự tay viết chiếu thư gửi bá quan văn võ, răn dạy giữ gìn phẩm chất thanh liêm, thương dân như con.', '1303-01-09', 'Trần Nhân Tông ban ngự bút răn dạy quan lại');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('24f5dcf8-154d-4cb7-98f1-01f9a214825e', '2026-05-22 07:52:35.683', NULL, 'Quan lại nhà Trần chính thức tiếp quản và lập sổ bạ hành chính cho vùng đất hai châu Ô, Lý (Thuận Hóa) do vua Chiêm Thành dâng làm sính lễ.', '1307-11-20', 'Đoàn nhượng đất hai châu Ô, Lý hoàn tất');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('c9ca37c6-8ac9-41c0-98ae-1e7361f16871', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần tiến hành đợt sát hạch quy mô lớn nhằm loại bỏ những kẻ giả tu mượn danh cửa Phật để trốn lính, trốn thuế.', '1309-04-02', 'Sát hạch tăng ni toàn quốc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('30739def-c067-4106-bd27-d19098a4e5aa', '2026-05-22 07:52:35.683', NULL, 'Trong chiến dịch bình định phía Nam, quân Trần đại thắng, bắt sống vua Chiêm là Chế Chí đưa về Thăng Long và lập người khác lên thay, giữ yên bờ cõi.', '1312-05-28', 'Trần Anh Tông bắt sống quốc vương Chiêm Thành');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4b04af7d-8fcf-4916-a176-b5058b1ea52c', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Minh Tông định lại chế độ cấp bổng lộc cho quan lại bằng lúa gạo và tiền lụa, đảm bảo đời sống để họ tận tâm cống hiến cho triều đình.', '1316-08-15', 'Cải cách chế độ lương bổng quan lại');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('2a9456a7-970e-48f7-90a9-4116718ebf6b', '2026-05-22 07:52:35.683', NULL, 'Triều đình tổ chức hội thề trang trọng tại đền Đồng Cổ (Thăng Long), bá quan văn võ cùng cắt máu ăn thề tuyệt đối trung thành với vương triều.', '1324-12-07', 'Tổ chức hội thề Đồng Cổ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('30c44d9d-8d52-40a2-b789-5991edf916ee', '2026-05-22 07:52:35.683', NULL, 'Thượng hoàng Trần Minh Tông nghe lời gièm pha, bức tử oan cha vợ là Quốc phụ Thái tể Trần Quốc Chẩn, để lại một vết nhơ lớn trong lịch sử trị vì.', '1328-03-24', 'Vụ án oan giết Trần Quốc Chẩn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('374abfc3-20c5-482a-b489-c9ef29fa6dfa', '2026-05-22 07:52:35.683', NULL, 'Triều đình ra lệnh cho các lộ vùng đồng bằng sông Hồng đắp thêm đê phụ và khơi thông các kênh rạch để chống úng ngập mùa mưa bão.', '1332-06-19', 'Sửa sang hệ thống đê điều vùng hạ lưu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('9a27bdb9-a2df-433f-9808-ffc9bf41674d', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Hiến Tông hạ lệnh kiểm tra lại ranh giới các điền trang của vương hầu, thu hồi những phần đất lấn chiếm trái phép của nông dân tự do.', '1339-09-11', 'Khám xét điền trang vương hầu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('bad3ed79-7dbe-4dd2-957f-af5404865901', '2026-05-22 07:52:35.683', NULL, 'Nhà Trần thành lập các đội thủy quân tuần tiễu chuyên trách bảo vệ an ninh vùng biển từ Thanh Hóa đến Nghệ An, phòng nạn hải tặc.', '1345-02-14', 'Thiết lập đội tuần dương ven biển');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('13ec06b9-c90b-44e5-815f-f7e088068367', '2026-05-22 07:52:35.683', NULL, 'Thiên tai dịch bệnh hoành hành, mùa màng thất bát, vua Trần Dụ Tông buộc phải ban chiếu xá thuế ruộng trên diện rộng để an dân.', '1354-07-22', 'Đói lớn, triều đình xá thuế ruộng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a8824f17-d458-4e7b-aea9-0f7576090cce', '2026-05-22 07:52:35.683', NULL, 'Đại thần Trương Hán Siêu, tác giả bài Bạch Đằng giang phú nổi tiếng, từ trần. Ông là trụ cột chính trị và văn hóa quan trọng cuối thời Trần.', '1358-10-08', 'Nhà Nho Trương Hán Siêu qua đời');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('df7b2b19-4f82-4f72-bb09-87451589d456', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Dụ Tông lơ là chính sự, vét cạn ngân khố bắt dân phu xây dựng các công trình xa hoa, hồ nước nhân tạo trong hoàng thành để thưởng ngoạn.', '1366-03-17', 'Vua Dụ Tông sa đọa, xây cung điện nguy nga');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e18e400d-f3f5-474a-9be1-bc60a10c25b7', '2026-05-22 07:52:35.683', NULL, 'Thượng hoàng Trần Nghệ Tông ban hành chính sách nhằm hạn chế số lượng nô tì trong các điền trang vương hầu, nhằm bổ sung nhân lực cho quân đội.', '1372-11-25', 'Ban hành quy định hạn chế nô tì');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f30515bb-79f9-4bd0-a26c-33acdb553462', '2026-05-22 07:52:35.683', NULL, 'Quân Chiêm Thành dưới sự chỉ huy của Chế Bồng Nga tấn công dữ dội vào phủ Nghệ An, đánh tan quân phòng thủ địa phương, cướp bóc vô số của cải.', '1378-05-14', 'Chiêm Thành cướp phá Nghệ An');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('36c845f6-b50e-48fd-9a7c-1d789a254018', '2026-05-22 07:52:35.683', NULL, 'Trước sức ép quân sự liên tục từ Chiêm Thành, triều đình nhà Trần quyết định di tản nhiều tài sản, châu báu và sách vở quan trọng từ Thăng Long về Thanh Hóa phòng thủ.', '1385-01-30', 'Chuyển bảo vật quốc gia về Thanh Hóa');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('de63f72e-265b-428d-aa65-0c1a2c6f73d0', '2026-05-22 07:52:35.683', NULL, 'Nhờ được Thượng hoàng Nghệ Tông sủng ái, Hồ Quý Ly được thăng chức Đồng bình chương sự (Tể tướng), nắm giữ toàn bộ quyền hành dân sự và quân sự cốt lõi.', '1387-04-18', 'Hồ Quý Ly được phong làm Đồng bình chương sự');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('818b30e5-b644-4784-97dd-94c062ff20d5', '2026-05-22 07:52:35.683', NULL, 'Quân đội nhà Trần do Hồ Quý Ly chỉ huy nếm mùi thất bại thảm hại trước quân Chiêm Thành tại sông Thanh Quyết, Quý Ly phải để thuộc tướng ở lại chống đỡ và rút chạy.', '1389-10-22', 'Quân Trần đại bại tại sông Thanh Quyết');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('e7284d85-ffdd-44b2-a29e-2966b39228a7', '2026-05-22 07:52:35.683', NULL, 'Cảm thấy bị đe dọa quyền lực, Hồ Quý Ly lên kế hoạch thanh trừng và tước bỏ binh quyền của danh tướng Trần Khát Chân cùng nhiều tướng lĩnh thân tín khác.', '1391-08-05', 'Hồ Quý Ly trừ khử tướng Trần Khát Chân');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d0fb200c-0e4d-4e29-8c2b-5843d95fd0b7', '2026-05-22 07:52:35.683', NULL, 'Vua Trần Thuận Tông xuống chiếu cấp tiền tu bổ, xây dựng đền thờ nhằm tôn vinh những người phụ nữ tiết liệt, giữ gìn phong hóa gia phong.', '1393-02-12', 'Sửa sang đền thờ các liệt nữ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('78b77200-f15b-473a-bb39-a7135c6b5a54', '2026-05-22 07:52:35.683', NULL, 'Hồ Quý Ly dùng quyền lực tối cao ép buộc toàn bộ bá quan văn võ và thương nhân phải giao dịch bằng tiền giấy Thông bảo hội sao, trừng trị nặng kẻ giấu tiền đồng.', '1395-07-09', 'Ép bá quan dùng tiền giấy');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1379d71b-4fa2-4dbe-854a-09f5171e9b06', '2026-05-22 07:52:35.683', NULL, 'Ban hành sắc lệnh phân cấp lại ngạch quan chức tại các xã, hương, quy định rõ trách nhiệm của các chức sắc trong việc đôn đốc thuế khóa và trị an.', '1397-09-28', 'Định lại quy chế hương phẩm địa phương');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b2590afb-5d2c-40ce-91b5-410aa45ea291', '2026-05-22 07:52:35.683', NULL, 'Hồ Quý Ly tổ chức cuộc thảm sát quy mô lớn, sát hại hàng trăm vương hầu, tôn thất và đại thần trung thành với dòng họ Trần để dập tắt mọi nguy cơ phản kháng.', '1398-11-15', 'Thảm sát trung thần nhà Trần');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f0e17f9e-a481-4b6f-ac21-b8a7cef416cf', '2026-05-22 07:52:35.683', NULL, 'Trần Khát Chân cùng các tông thất nhà Trần mưu sát Hồ Quý Ly tại hội thề Đốn Sơn (Thanh Hóa) nhưng việc bại lộ, hàng trăm người bị bắt và xử tử, chấm dứt hy vọng phục nghiệp.', '1399-04-03', 'Hội thề Đốn Sơn thất bại');



INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8f9b1db9-0510-4ad8-ac96-e9bb602f252d', '2026-05-22 07:58:12.679', NULL, 'Nữ hoàng cuối cùng của nhà Lý - Lý Chiêu Hoàng chính thức ban sắc chiếu nhường ngôi vị cho chồng là Trần Cảnh, hoàn tất cuộc chuyển giao vương quyền lịch sử mở ra triều đại nhà Trần.', '1225-12-31', 'Lý Chiêu Hoàng ban chiếu truyền ngôi cho Trần Cảnh');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ea9a06ce-a32f-44db-9741-d92312ebeb35', '2026-05-22 07:58:12.679', NULL, 'Trần Thái Tông ban sắc lệnh đầu tiên quy chuẩn hóa các nghi tiết triều nghi, dâng lễ vật và thưởng phạt quan chức tại Thăng Long vào tết Đoan Ngọ.', '1226-05-05', 'Quy định lại lễ nghi cung đình dịp Tết Đoan Ngọ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a148f739-b29b-4a15-91dc-d68dc09b2a84', '2026-05-22 07:58:12.679', NULL, 'Triều đình tổ chức lễ đại xá, giảm thuế và tha bổng cho nhiều phạm nhân nhằm ăn mừng chiến dịch dẹp loạn ổn định biên cương phía Nam hoàn thành.', '1227-10-10', 'Đại xá thiên hạ sau khi dẹp yên biên ải');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('70bf1478-679d-483b-b10d-755ac83b2ef3', '2026-05-22 07:58:12.679', NULL, 'Nhà Trần ban hành quy định thiết lập các trạm dịch ngựa dọc tuyến đường huyết mạch quốc gia để phục vụ việc chuyển công văn khẩn cấp của triều đình.', '1231-12-25', 'Thiết lập hệ thống trạm dịch dọc đường lý trình');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('82d0f410-b687-40fa-8d2f-1d0568af3a5a', '2026-05-22 07:58:12.679', NULL, 'Thái sư Trần Thủ Độ chủ trì đại lễ khánh thành đợt trùng tu quy mô lớn Giảng Võ Đường tại Thăng Long nhằm nâng cao năng lực huấn luyện quân đội.', '1233-08-14', 'Khánh thành công trình tu bổ Giảng Võ Đường');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('790b6e22-c2b0-434e-a8ff-75000168658c', '2026-05-22 07:58:12.679', NULL, 'Do mâu thuẫn hôn nhân gia tộc phu nhân, Thái úy Trần Liễu tập hợp tư binh nổi loạn trên sông Hồng chống lại triều đình trước khi ra hàng xin vua em tạ tội.', '1237-04-03', 'Biến cố binh biến của Thái úy Trần Liễu trên sông Hồng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('76a4350f-d5e3-4570-8060-4eb476fe994f', '2026-05-22 07:58:12.679', NULL, 'Vua Trần Thái Tông hạ chiếu cho các quan địa phương trùng tu khu mộ tổ và hành cung của dòng họ Trần tại vùng đất Thanh Hóa.', '1241-05-12', 'Trùng tu tổ miếu hoàng tộc tại Thanh Hóa');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ad201ac3-88d2-476b-b26e-6fdf7f6db0a2', '2026-05-22 07:58:12.679', NULL, 'Nhà Trần cho đúc một chiếc chuông đồng lớn treo trước điện thiết triều, cho phép người dân có oan ức thấu trời được đến gõ chuông xin hoàng đế trực tiếp xét xử.', '1244-03-20', 'Đặt chuông lớn tại thềm điện triều đình để dân kêu oan');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6012eb19-e118-4c13-8b75-db305d0e514b', '2026-05-22 07:58:12.679', NULL, 'Ban sắc lệnh quy định các kỳ thi Thái học sinh (đại khoa tuyển tiến sĩ) sẽ được tổ chức đều đặn 7 năm một lần để tìm kiếm hiền tài cho đất nước.', '1246-07-15', 'Quy chuẩn hóa khoa cử Thái học sinh định kỳ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('9335ed37-b751-4ca0-93d6-4fa6b95b3ef1', '2026-05-22 07:58:12.679', NULL, 'Triều đình ban hành luật nghiêm cấm các hào trưởng, quan lại lạm dụng quyền lực ép buộc dân tự do hoán đổi thân phận thành nô tì gia binh.', '1247-02-11', 'Ban sắc lệnh cấm cưỡng bức lương dân làm nô tì');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('baa2362b-1f2e-41bf-9704-9c13da15b96e', '2026-05-22 07:58:12.679', NULL, 'Do vương quốc Chiêm Thành liên tục quấy nhiễu cướp bóc vùng biên thùy phía Nam, hoàng đế Trần Thái Tông chỉ huy đại quân viễn chinh phạt Chiêm để ổn định bờ cõi.', '1252-04-19', 'Trần Thái Tông thân chinh viễn chinh Chiêm Thành');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('a1a216d0-bded-42fb-ada0-25f1f0c3b994', '2026-05-22 07:58:12.679', NULL, 'Nhà Trần cho xây dựng Viện Quốc Học tại Thăng Long, đắp tượng Chu Công, Khổng Tử để làm nơi giảng dạy kinh thư, mở rộng giáo dục Nho học chính thống.', '1253-02-15', 'Thành lập Viện Quốc Học đào tạo kinh điển');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('5074cdb3-2e52-4af4-b29d-abf7eb9a3906', '2026-05-22 07:58:12.679', NULL, 'Trước dự báo lũ lớn, triều đình ra lệnh tổng động viên quân dân gia cố tuyến đê bao quanh kinh thành Thăng Long, hình thành hệ thống đê quai vạc kiên cố.', '1255-06-10', 'Huy động đắp đê quai vạc Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('bb57806e-1e47-4e15-a8ef-bb416e84beb8', '2026-05-22 07:58:12.679', NULL, 'Trước tin tình báo quân Mông Cổ áp sát biên thùy, vua Trần Thái Tông chính thức phong Trần Quốc Tuấn chỉ huy cấm quân trấn giữ tuyến biên giới then chốt.', '1257-08-24', 'Ủy thác quyền thống lĩnh biên giới cho Trần Quốc Tuấn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('cf2441ec-cc23-46c4-80bc-dabd20c1fccf', '2026-05-22 07:58:12.679', NULL, 'Sau khi đánh tan quân Nguyên Mông tại Đông Bộ Đầu buộc giặc rút lui, Thượng hoàng Thái Tông và vua Thánh Tông long trọng tổ chức đại lễ phục hồi kinh thành.', '1258-02-24', 'Đại lễ rước xa giá hoàng gia trở lại kinh đô Thăng Long');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('78272f88-f586-41f0-8368-ccf3f209d709', '2026-05-22 07:58:12.679', NULL, 'Triều đình ban hành văn bản quy pháp định rõ quyền hạn sử dụng, mua bán và thừa kế đối với đất đai điền trang của các tôn thất vương tộc nhà Trần.', '1259-11-03', 'Chính thức hóa quyền thừa kế điền trang vương hầu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('88b22b2c-8d4c-456e-a350-b04e511e2fb5', '2026-05-22 07:58:12.679', NULL, 'Thượng hoàng Trần Thái Tông ngự tuần phủ Thiên Trường (Nam Định), hạ lệnh xây dựng cung điện Trùng Quang, Trùng Hoa biến nơi đây thành trung tâm quyền lực thứ hai.', '1262-10-14', 'Nâng cấp phủ Thiên Trường thành bồi đô');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('edb745f8-33fc-4940-9cd5-3c2c800c1f31', '2026-05-22 07:58:12.679', NULL, 'Nhà Trần ban bố chính sách cho phép các vương hầu, công chúa chiêu mộ dân phiêu tán không có ruộng đất để khai hoang vùng đầm lầy, lập nên hệ thống điền trang lớn.', '1266-03-25', 'Xuống chiếu cho tôn thất khai khẩn điền trang');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6c551802-4136-46cd-af3d-f84bc757b5e3', '2026-05-22 07:58:12.679', NULL, 'Hoàng đế nhà Nguyên gửi phái đoàn ngoại giao mang sắc phong vương cho vua Trần Thánh Tông, kèm theo các yêu sách ngầm nhằm thăm dò ý chí độc lập của nước ta.', '1271-02-20', 'Hốt Tất Liệt gửi thư phong vương thăm dò Đại Việt');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('1107cdbd-eadb-4e02-90db-05db8ba83d83', '2026-05-22 07:58:12.679', NULL, 'Do thiên tai bão lụt tàn phá mùa màng nghiêm trọng, vua Trần Dụ Tông xuống chiếu xá bỏ toàn bộ tô thuế năm Tân Tỵ cho nông dân nghèo tại các lộ bị ảnh hưởng.', '1341-08-11', 'Ban lệnh miễn sưu thuế toàn diện cho vùng lụt lội');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('66d367a6-7a17-46ec-8161-37c607c7e0ab', '2026-05-22 07:58:12.679', NULL, 'Hàng vạn quan lại và người dân nhà Tống vượt biển tị nạn quân Nguyên tràn xuống nước ta. Nhà Trần cho phép định cư, lập nghiệp tại vùng cửa sông ven biển.', '1274-04-12', 'Thu nhận di dân nhà Tống lánh nạn quân Nguyên');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('0bba8b92-7618-41b3-adc0-fd1fb1d75d88', '2026-05-22 07:58:12.679', NULL, 'Nhà Trần tổ chức đợt tổng kiểm tra quân sự, sát hạch năng lực võ thuật và bày binh bố trận của toàn bộ tướng lĩnh trung cao cấp để tuyển chọn nhân tài quân sự.', '1275-11-05', 'Đại sới khảo hạch võ nghệ tại điện Tập Hiền');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7ab17c1e-59f0-4dc7-9a4c-7135b46cca85', '2026-05-22 07:58:12.679', NULL, 'Nhà vua đích thân lĩnh binh tiến sâu vào vùng núi phía Tây tiễu trừ các thế lực nổi dậy cấu kết với thế lực nước ngoài quấy rối dân lành.', '1277-12-15', 'Vua Trần Thánh Tông親征 dẹp loạn biên giới phía Tây');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ce8957b2-b595-41ff-a9b2-2b004ed95fd7', '2026-05-22 07:58:12.679', NULL, 'Triều đình điều chỉnh mức thuế thương mại đánh vào mặt hàng muối chiến lược và các sản vật quý từ miền núi đem về xuôi, nhằm tăng nguồn thu công quỹ.', '1278-06-10', 'Cải cách sắc thuế sản vật muối và lâm thổ sản');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('bf332bb0-6b79-4778-93be-8f586573fc01', '2026-05-22 07:58:12.679', NULL, 'Vua Trần Nhân Tông cử sứ bộ mang sản vật sang chúc thọ hoàng đế nhà Nguyên, thực chất là thực hiện nhiệm vụ tình báo chiến lược nắm bắt nội tình triều đình giặc.', '1281-10-22', 'Phái đoàn ngoại giao Đại Việt sang Khanbaliq');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('79ecfc08-6721-432b-8506-a36e121e4224', '2026-05-22 07:58:12.679', NULL, 'Dưới sự chứng kiến của vua Trần Nhân Tông, lễ duyệt binh vĩ đại diễn ra tại bến Đông Bộ Đầu. Trần Quốc Tuấn chính thức nhận quyền tổng chỉ huy quân đội toàn quốc.', '1283-10-09', 'Đại duyệt binh Đông Bộ Đầu và trao ấn Tiết chế');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('fafa9294-6c74-41a4-b1f7-a029102555f2', '2026-05-22 07:58:12.679', NULL, 'Quốc công tiết chế ban bố mệnh lệnh mật yêu cầu toàn thể nhân dân kinh thành và các lộ trọng điểm sẵn sàng sơ tán, cất giấu lương thực khi giặc Nguyên tràn qua.', '1284-11-15', 'Hạ chiếu thực thi chiến lược Vườn không nhà trống');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8e7f2d67-d98c-4581-b8d0-6b3f8f1c4e74', '2026-05-22 07:58:12.679', NULL, 'Cấm quân nhà Trần kiên cường chặn đánh lực lượng tiên phong của Thống soái Thoát Hoan tại tuyến phòng thủ sông Cầu, gây tổn thất lớn cho kỵ binh giặc.', '1285-01-20', 'Trận chiến phòng thủ khốc liệt tại sông Cầu');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('ae331a23-d3d3-4e1c-8aeb-f838bf091e6f', '2026-05-22 07:58:12.679', NULL, 'Bị bắt tại trận đánh sông Thiên Mạc khi chặn hậu cho thiên tử rút lui, Trần Bình Trọng khảng khái mắng giặc: ''Thà làm quỷ nước Nam chứ không thèm làm vương đất Bắc''.', '1285-02-12', 'Anh hùng Trần Bình Trọng hy sinh danh liệt sử xanh');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('6323d3c7-c64a-4df7-b2ef-64beef366015', '2026-05-22 07:58:12.679', NULL, 'Lực lượng phối hợp giữa quân Trần và phục binh của nghĩa quân Hoa kiều do Trần Nhật Duật chỉ huy đánh tan tành hạm đội thuyền chiến nhà Nguyên tại bến Hàm Tử.', '1285-05-20', 'Đại thắng trận Hàm Tử đập tan thủy quân địch');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('839f9a12-63dd-4910-8d1a-89b571affd17', '2026-05-22 07:58:12.679', NULL, 'Quân dân nhà Trần ca khúc khải hoàn tổng tấn công vào Thăng Long, đánh đuổi hoàn toàn tàn quân của Thoát Hoan tháo chạy, khôi phục lại chủ quyền quốc gia.', '1285-06-15', 'Giải phóng kinh thành Thăng Long hoàn toàn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('f7fe6845-fd1f-4bc0-bd0e-f6d4cd874d53', '2026-05-22 07:58:12.679', NULL, 'Căm phẫn vì liên tiếp thất bại, hoàng đế nhà Nguyên hạ chỉ huy động 30 vạn đại quân cùng hàng ngàn thuyền lương do Ô Mã Nhi dẫn đầu quyết tâm xâm lược nước ta lần 3.', '1287-03-10', 'Hốt Tất Liệt hạ lệnh tổng động viên phục hận Đại Việt');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('b61a3574-43d8-406e-aff9-0d5dfc1aa1b5', '2026-05-22 07:58:12.679', NULL, 'Danh tướng Trần Khánh Dư mưu trí phục kích tại eo biển Vân Đồn, tiêu diệt hoàn toàn đoàn thuyền tải lương khổng lồ của Trương Văn Hổ, đẩy giặc vào thế thiếu lương suy kiệt.', '1287-11-05', 'Đại thắng thủy chiến Vân Đồn bẻ gãy đoàn thuyền lương');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('305c37fb-9521-4d11-85b4-08753f1cca10', '2026-05-22 07:58:12.679', NULL, 'Trần Quốc Tuấn chỉ huy quân dân thực hiện cuộc tản cư chiến lược khỏi hoàng thành Thăng Long, biến nơi đây thành vườn không nhà trống bỏ lại cái bẫy trống rỗng cho giặc.', '1288-01-22', 'Chủ động rút lui chiến lược khỏi Thăng Long lần thứ ba');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('edcb178f-3ed4-40a0-8d9e-151150a4798a', '2026-05-22 07:58:12.679', NULL, 'Triều đình mở đại hội phong thưởng đất đai, tước vị long trọng cho các tướng lĩnh có công trạng lớn trong hai cuộc kháng chiến vĩ đại chống quân Nguyên Mông.', '1289-04-30', 'Lễ định công ban thưởng công thần kháng chiến');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('7d5c98a6-6924-4900-b8b8-73dd0a13a419', '2026-05-22 07:58:12.679', NULL, 'Hoàng đế Trần Nhân Tông chính thức làm lễ truyền ngôi cho thái tử Trần Thuyên (Trần Anh Tông) rồi lui về phủ Thiên Trường làm Thượng hoàng, dọn đường tu hành.', '1293-04-16', 'Trần Nhân Tông nhường ngôi cho Trần Anh Tông');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('d076a778-d644-4e6f-9080-5b70131c846f', '2026-05-22 07:58:12.679', NULL, 'Điều ngự Giác hoàng Trần Nhân Tông chính thức xuống tóc, lên đỉnh non thiêng Yên Tử tu hành khổ hạnh, thống nhất phật giáo khai sinh ra Thiền phái Trúc Lâm Yên Tử độc lập.', '1299-08-11', 'Trần Nhân Tông lên núi Yên Tử sáng lập Thiền phái Trúc Lâm');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('770b57de-6ef9-4be3-b15a-c140b1062a22', '2026-05-22 07:58:12.679', NULL, 'Triều đình công bố kết quả khoa thi đình năm Giáp Thìn, vinh danh Trạng nguyên Mạc Đĩnh Chi - người sau này trở thành vị đại sứ kiệt xuất danh xưng Lưỡng quốc Trạng nguyên.', '1304-10-05', 'Kỳ thi Thái học sinh vinh danh Trạng nguyên Mạc Đĩnh Chi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('55626203-0e0c-419d-a304-4bdee3bddff6', '2026-05-22 07:58:12.679', NULL, 'Thực hiện lời hứa bang giao của Thượng hoàng Nhân Tông, công chúa Huyền Trân chính thức lên thuyền gả cho vua Chiêm Thành Chế Mân để đổi lấy đất hai châu Ô, Lý.', '1306-06-12', 'Huyền Trân Công chúa lên đường thành hôn cùng Chế Mân');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('21450246-eeb0-4386-9753-baa1e7508832', '2026-05-22 07:58:12.679', NULL, 'Nhà Trần điều động hàng vạn hộ dân nghèo từ miền xuôi vào định cư, khai phá và lập làng ấp hành chính mới tại vùng Thuận Châu và Lý Châu vừa sáp nhập.', '1313-03-15', 'Tổ chức di dân quy mô lớn khai hoang hai châu mới');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('251c88c9-3e06-4420-af87-9ebcf8b3aaec', '2026-05-22 07:58:12.679', NULL, 'Các thợ kiến trúc hoàng gia hoàn thành việc xây dựng và nâng cấp ngọn tháp gạch Phổ Minh cao 14 tầng tại Nam Định, nơi lưu giữ xá lỵ của Phật hoàng Trần Nhân Tông.', '1321-09-18', 'Hoàn thành trùng tu bảo tháp Phổ Minh cao tầng');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('67620bfc-72be-4ef3-b35e-81161666e1cc', '2026-05-22 07:58:12.679', NULL, 'Vua Trần Minh Tông cử đoàn nội thị và tướng phòng biên đi kiểm tra ranh giới, cắm các mốc tiêu khẳng định chủ quyền lãnh thổ vững chắc trước các hành vi lấn chiếm.', '1325-05-20', 'Cắm mốc chủ quyền cương giới tại biên cương phía Bắc');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('589f224a-181b-48af-a1de-8c136b8f7370', '2026-05-22 07:58:12.679', NULL, 'Trước tình hình biên giới phía Tây bị quân Ai Lao quấy nhiễu liên miên, Thượng hoàng Minh Tông tự mình cầm quân viễn chinh vào vùng núi Nghệ An để tiễu phạt.', '1334-12-25', 'Thượng hoàng Trần Minh Tông thân chinh phạt Ai Lao');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('3f1a7500-e8bf-4411-bc50-21507d79bb7e', '2026-05-22 07:58:12.679', NULL, 'Danh sĩ Nguyễn Trung Ngạn chấp bút soạn và cho đục trực tiếp bài văn bia ca ngợi võ công oanh liệt của nhà Trần lên vách núi đá dựng đứng tại Kỳ Sơn (Nghệ An).', '1335-02-14', 'Nguyễn Trung Ngạn soạn bia ma nhai ghi võ công trên vách núi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4c1fe61d-5348-4227-b2e0-90dbcf4637f1', '2026-05-22 07:58:12.679', NULL, 'Mất mùa đói kém diện rộng tại dải đất miền Trung, vua Trần Dụ Tông hạ lệnh mở toàn bộ các kho thóc dự trữ quốc gia vận chuyển bằng đường thủy cứu tế bá tánh.', '1356-05-12', 'Xuống chiếu xuất kho lương cứu tế khẩn cấp dân Thanh Nghệ');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('54c798d8-4130-4b66-a22d-4242bbe4a6c2', '2026-05-22 07:58:12.679', NULL, 'Nhà Trần cải cách chế độ thi cử, lần đầu tiên tổ chức đầy đủ vòng thi Đình tại sân rồng cung điện để trực tiếp phân định danh hiệu Trạng nguyên, Bảng nhãn, Thám hoa.', '1374-03-22', 'Tổ chức khoa thi Đình đầu tiên định rõ Tam khôi');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('4015e96c-e228-4e3d-b50f-4ea2bcaf41b8', '2026-05-22 07:58:12.679', NULL, 'Do chủ quan khinh địch rơi vào trận địa phục kích tàn khốc của bạo chúa Chiêm Thành Chế Bồng Nga, hoàng đế Trần Duệ Tông cùng hàng vạn cấm quân hy sinh tại thành Đồ Bàn.', '1377-02-28', 'Vua Trần Duệ Tông tử trận tại thành Đồ Bàn');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('92bdae76-c7cd-42a2-89ed-eb4b0d387335', '2026-05-22 07:58:12.679', NULL, 'Nhận được mật báo chỉ điểm từ hàng tướng Chiêm, đô tướng Trần Khát Chân ra lệnh cho pháo binh cấm quân tập trung hỏa lực bắn dữ dội vào thuyền ngự, tiêu diệt Chế Bồng Nga tại trận.', '1390-02-05', 'Trần Khát Chân bắn chết bạo chúa Chế Bồng Nga trên sông Hải Triều');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('8eacf39b-14c2-4677-a93f-8389dd992c5c', '2026-05-22 07:58:12.679', NULL, 'Ngoại thích Hồ Quý Ly đôn đốc hàng vạn dân phu xây dựng thần tốc tòa thành kiên cố hoàn toàn bằng các khối đá khổng lồ tại Thanh Hóa (Thành nhà Hồ) nhằm chuẩn bị dời đô.', '1394-05-14', 'Hồ Quý Ly hoàn thành xây dựng kiên thành Tây Đô');

INSERT INTO on_this_day (id, created_at, updated_at, description, event_date, title)
VALUES ('802dbe6b-430c-4b2f-8787-3d2cef80dc95', '2026-05-22 07:58:12.679', NULL, 'Hồ Quý Ly mượn danh nghĩa vua Trần Thuận Tông ban sắc lệnh ép buộc toàn bộ triều đình, hoàng tộc và các cơ quan hành chính trung ương di tản từ Thăng Long vào Thanh Hóa.', '1397-03-15', 'Ban bố sắc chỉ dời kinh đô từ Thăng Long vào Tây Đô');

